create table if not exists public.guru(id bigint generated by default as identity primary key,nama text not null,jabatan text default 'Anggota / Guru',sekolah text,created_at timestamptz default now());create table if not exists public.berita(id bigint generated by default as identity primary key,judul text not null,ringkasan text,tanggal text,created_at timestamptz default now());create table if not exists public.agenda(id bigint generated by default as identity primary key,tanggal text not null,bulan text not null,judul text not null,lokasi text,created_at timestamptz default now());create table if not exists public.galeri(id bigint generated by default as identity primary key,judul text not null,url text not null,created_at timestamptz default now());create table if not exists public.informasi(id bigint generated by default as identity primary key,judul text not null,isi text,created_at timestamptz default now());alter table public.guru enable row level security;alter table public.berita enable row level security;alter table public.agenda enable row level security;alter table public.galeri enable row level security;alter table public.informasi enable row level security;create policy "Public read guru" on public.guru for select using(true);create policy "Public read berita" on public.berita for select using(true);create policy "Public read agenda" on public.agenda for select using(true);create policy "Public read galeri" on public.galeri for select using(true);create policy "Public read informasi" on public.informasi for select using(true);